import pandas as pd

try:
    # Read all sheets, header=2 to get correct headers (since Row 3 is headers)
    # Actually, pandas `read_excel` with `header=1` worked for titles.
    # But now we know Row 3 is header (index 2).
    # However, for `Growth Analysis`, headers are on Row 3 (Index 2).

    # Let's just search for '???' as string in all cells.
    xls = pd.ExcelFile('nasa_budget_recovered.xlsx')

    print("Checking for remaining '???'...")
    found_any = False
    for sheet_name in xls.sheet_names:
        df = pd.read_excel(xls, sheet_name=sheet_name, header=None)
        # Check for '???'
        for col in df.columns:
            if df[col].astype(str).str.contains(r'\?\?\?').any():
                print(f"Sheet '{sheet_name}' still has '???' in column {col}")
                found_any = True

    if not found_any:
        print("Success! No '???' found.")
    else:
        print("Failed: Some '???' remain.")

except Exception as e:
    print(f"Error: {e}")

